  async function tenants(user){shell(user,'Tenants',head('People','Tenants','Search and manage tenants.','<button class="btn primary" id="add">+ Add Tenant</button>')+'<div id="list" class="loading">Loading…</div>');document.querySelector('#add').onclick=()=>tenantForm(user);try{const rows=await api('/tenants');document.querySelector('#list').innerHTML=rows.length?'<div class="toolbar"><input id="search" placeholder="Search name, phone or email…"></div><div class="table-wrap"><table class="table"><thead><tr><th>Name</th><th>Phone</th><th>Email</th><th>Property</th><th>Unit</th><th>Rent</th></tr></thead><tbody id="rows"></tbody></table></div>':'<div class="card empty"><strong>No tenants yet.</strong><button class="btn primary" id="first">Add Tenant</button></div>';if(!rows.length){document.querySelector('#first').onclick=()=>tenantForm(user);return;}const render=()=>{const q=document.querySelector('#search').value.toLowerCase();document.querySelector('#rows').innerHTML=rows.filter(x=>JSON.stringify(x).toLowerCase().includes(q)).map(x=>`<tr class="link" onclick="location='/tenants/${x.id}'"><td><b>${esc(x.name)}</b></td><td>${esc(x.phone||'—')}</td><td>${esc(x.email||'—')}</td><td>${esc(x.current_property||'—')}</td><td>${esc(x.current_unit||'—')}</td><td>${money(x.current_rent)}</td></tr>`).join('');};document.querySelector('#search').oninput=render;render();}catch(e){document.querySelector('#list').innerHTML='<div class="error">'+esc(e.message)+'</div>';}}
