  async function wizard(user,pid,uid,tid){
    let step=pid?(uid?3:2):(tid?3:1);
    const state={property_id:pid||'',unit_id:uid||'',tenant_id:tid||'',tenant_mode:'existing'};
    const render=async()=>{
      const ps=await api('/properties'),ts=await api('/tenants'),us=state.property_id?await api('/properties/'+state.property_id+'/units'):[];
      let body='';
      if(step===1)body=select('Property *','property_id',ps.map(p=>[p.id,p.name]),state.property_id);
      if(step===2)body=select('Vacant unit *','unit_id',us.filter(x=>x.status==='vacant').map(x=>[x.id,x.unit_number]),state.unit_id);
      if(step===3)body=select('Tenant action','tenant_mode',[['existing','Select existing tenant'],['new','Create new tenant']],state.tenant_mode)+ (state.tenant_mode==='new'?input('Tenant name *','new_name')+input('Phone','new_phone','','tel')+input('Email','new_email','','email'):select('Existing tenant *','tenant_id',ts.map(t=>[t.id,t.name]),state.tenant_id));
      if(step===4)body=input('Start date *','start_date',today(),'date')+input('End date','end_date','','date')+input('Monthly rent *','monthly_rent','','number','min="0" step="0.01"')+input('Security deposit','security_deposit',0,'number','min="0" step="0.01"')+input('Rent due day','rent_due_day',5,'number','min="1" max="31"')+input('Notice period (days)','notice_period_days',30,'number','min="0"')+select('Escalation type','rent_escalation_type',[['none','None'],['percentage','Percentage'],['fixed_amount','Fixed amount']],'none')+input('Escalation value','rent_escalation_value',0,'number','min="0" step="0.01"')+input('Escalation interval (months)','rent_escalation_interval_months','','number','min="1"')+select('Billing proration','billing_proration_strategy',[['full_month','Full month'],['prorated_actual_days','Prorated actual days']],'full_month');
      if(step===5)body=select('Electricity meter','electricity_meter',[['skip','Skip'],['add','Add meter']],'skip')+input('Electricity meter number','electricity_meter_number','','text')+select('Water meter','water_meter',[['skip','Skip'],['add','Add meter']],'skip')+input('Water meter number','water_meter_number','','text');
      if(step===6)body=select('Utility','utility_choice',[['none','Skip for now'],['electricity','Electricity'],['water','Water']],'none')+select('Billing method','billing_method',[['per_unit','Per unit'],['per_unit_fixed','Per unit + fixed'],['fixed','Fixed'],['slab','Slab'],['included_in_rent','Included in rent']],'per_unit')+input('Rate per unit','rate_per_unit','','number','min="0" step="0.0001"')+input('Fixed charge','fixed_charge',0,'number','min="0" step="0.01"')+input('Effective from','effective_from',today(),'date');
      shell(user,'Set Up Rental Unit',head('Guided setup','Property → Unit → Tenant → Lease → Meters → Utility','Each step uses the normal property, tenant, lease, meter and utility entities.')+form('wizard-form','Step '+step+' of 6',body,step<6?'Continue':'Finish setup'));
      const mode=document.querySelector('[name=tenant_mode]');if(mode)mode.onchange=()=>{state.tenant_mode=mode.value;render()};
      document.querySelector('#wizard-form').onsubmit=async e=>{
        e.preventDefault();const b=formData(e);
        if(step===1){state.property_id=b.property_id;step=2;return render()}
        if(step===2){state.unit_id=b.unit_id;step=3;return render()}
        if(step===3){state.tenant_mode=b.tenant_mode;if(b.tenant_mode==='new'){if(!b.new_name?.trim()){setErr('wizard-form',Error('Tenant name is required.'));return}try{const t=await api('/tenants',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({name:b.new_name,phone:b.new_phone,email:b.new_email})});state.tenant_id=t.id}catch(x){setErr('wizard-form',x);return}}else{state.tenant_id=b.tenant_id}step=4;return render()}
        if(step===4){try{const lease=await api('/leases',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({unit_id:state.unit_id,tenant_id:state.tenant_id,start_date:b.start_date,end_date:b.end_date||null,monthly_rent:b.monthly_rent,security_deposit:b.security_deposit,rent_due_day:b.rent_due_day,notice_period_days:b.notice_period_days,rent_escalation_type:b.rent_escalation_type,rent_escalation_value:b.rent_escalation_value,rent_escalation_interval_months:b.rent_escalation_interval_months||null,billing_proration_strategy:b.billing_proration_strategy,status:'active'})});state.lease_id=lease.id;toast('Lease created. Continue with optional setup.');step=5;return render()}catch(x){setErr('wizard-form',x);return}}
        if(step===5){for(const type of ['electricity','water']){if(b[type+'_meter']==='add'){const number=b[type+'_meter_number'];if(!number?.trim()){setErr('wizard-form',Error(type+' meter number is required.'));return}try{await api('/meters',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({unit_id:state.unit_id,utility_type:type,meter_number:number,installation_date:today(),status:'active'})})}catch(x){setErr('wizard-form',x);return}}}step=6;return render()}
        if(step===6){if(b.utility_choice!=='none'){try{await api('/utility-configs',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({unit_id:state.unit_id,utility_type:b.utility_choice,billing_method:b.billing_method,rate_per_unit:b.rate_per_unit||0,fixed_charge:b.fixed_charge||0,effective_from:b.effective_from})})}catch(x){setErr('wizard-form',x);return}}toast('Rental unit setup completed.');location='/properties/'+state.property_id+'/units/'+state.unit_id}
      };
    };
    render().catch(e=>shell(user,'Set Up Rental Unit','<div class="error">'+esc(e.message)+'</div>'));
  }
