  function billingStatus(v){return status(v==='METER_READING_REQUIRED'?'meter_reading_required':v);}function aiMini(rows){return rows?.length?'<div class="insight-mini-list">'+rows.map(i=>'<div class="insight-mini"><span class="pill '+(i.severity==='WARNING'?'warning':i.severity==='ATTENTION'?'partial':'paid')+'">'+esc(i.severity)+'</span><span><b>'+esc(i.title)+'</b><small>'+esc(i.summary)+'</small></span></div>').join('')+'</div>':'<div class="empty">No active insights yet. Generate the current period to analyze changes.</div>';}
  const overdueDays=d=>{if(!d)return 0;const a=new Date(d+'T00:00:00Z'),b=new Date();b.setUTCHours(0,0,0,0);return Math.max(0,Math.floor((b-a)/86400000));};
  function billingPage(user,month=new Date().toISOString().slice(0,7),filters={}){
    let data=[];
    const load=async()=>{try{const qs=new URLSearchParams({month,...Object.fromEntries(Object.entries(filters).filter(([,v])=>v))});data=await api('/billing/monthly?'+qs);const s=await api('/billing/summary?month='+month);render(s);}catch(e){const n=document.querySelector('#billing-body');if(n)n.innerHTML='<div class="error">'+esc(e.message)+'</div>';}};
    const render=s=>{const props=[...new Map(data.map(x=>[x.property_id,x.property])).entries()];shell(user,'Billing Center',head('Operations','Billing Center','Monthly rent and utility billing.','<div class="month-nav"><a class="btn secondary small" href="/reports">Financial report</a><a class="btn secondary small" href="/expenses">Expenses</a><a class="btn secondary small" href="/reports?aging=1">Aging</a><button class="icon-btn" id="prev">‹</button><span class="month-label">'+monthLabel(month)+'</span><button class="icon-btn" id="next">›</button></div>')+'<div class="billing-toolbar"><div class="toolbar"><input id="bsearch" placeholder="Search property, unit or tenant…" value="'+esc(filters.q||'')+'"><select id="bstatus"><option value="">All statuses</option><option value="READY">Ready</option><option value="METER_READING_REQUIRED">Meter Reading Required</option><option value="GENERATED">Generated</option><option value="PAID">Paid</option><option value="PARTIALLY_PAID">Partially Paid</option><option value="OVERDUE">Overdue</option></select><select id="bproperty"><option value="">All properties</option>'+props.map(p=>'<option value="'+esc(p[0])+'" '+(filters.property_id===p[0]?'selected':'')+'>'+esc(p[1])+'</option>').join('')+'</select><select id="butility"><option value="">All utilities</option><option value="electricity" '+(filters.utility==='electricity'?'selected':'')+'>Electricity</option><option value="water" '+(filters.utility==='water'?'selected':'')+'>Water</option></select></div><button class="btn primary" id="bulk">Generate All Ready Bills</button></div>'+
      '<div class="billing-kpis"><div class="card kpi"><div class="label">Units to Bill</div><div class="value">'+s.billable_units+'</div></div><div class="card kpi"><div class="label">Bills Generated</div><div class="value">'+s.generated+'</div></div><div class="card kpi"><div class="label">Ready</div><div class="value">'+s.ready+'</div></div><div class="card kpi"><div class="label">Meter Readings Required</div><div class="value">'+s.meter_readings_required+'</div></div><div class="card kpi"><div class="label">Paid</div><div class="value">'+s.paid+'</div></div><div class="card kpi"><div class="label">Partially Paid</div><div class="value">'+s.partially_paid+'</div></div><div class="card kpi"><div class="label">Overdue</div><div class="value">'+s.overdue+'</div></div><div class="card kpi"><div class="label">Expected</div><div class="value">'+money(s.expected)+'</div></div><div class="card kpi"><div class="label">Collected</div><div class="value">'+money(s.collected)+'</div></div><div class="card kpi"><div class="label">Outstanding</div><div class="value">'+money(s.outstanding)+'</div></div></div>'+
      '<section class="card collection-card"><div class="section-head"><h2>Monthly Collection</h2><b>'+Number(s.collection_rate||0).toFixed(1)+'%</b></div><div class="progress"><span style="width:'+Math.min(100,Number(s.collection_rate||0))+'%"></span></div><div class="collect-row"><div>Expected<b>'+money(s.expected)+'</b></div><div>Collected<b>'+money(s.collected)+'</b></div><div>Outstanding<b>'+money(s.outstanding)+'</b></div><div>Rate<b>'+Number(s.collection_rate||0).toFixed(1)+'%</b></div></div></section>'+
      '<section class="card"><div class="section-head"><h2>'+monthLabel(month)+' Billing</h2><span class="muted">'+data.length+' billable unit'+(data.length===1?'':'s')+'</span></div><div class="table-wrap billing-desktop"><table class="table"><thead><tr><th>Property</th><th>Unit</th><th>Tenant</th><th>Rent</th><th>Electricity</th><th>Water</th><th>Total</th><th>Paid</th><th>Outstanding</th><th>Due</th><th>Status</th><th>Action</th></tr></thead><tbody>'+(data.length?data.map(billingRow).join(''):'<tr><td colspan="12" class="empty">No billable leases for this month.</td></tr>')+'</tbody></table></div><div class="billing-mobile">'+(data.length?data.map(billingCard).join(''):'<div class="empty">No billable leases for this month.</div>')+'</div></section><div id="billing-body"></div>');
      document.querySelector('#prev').onclick=()=>billingPage(user,monthShift(month,-1),filters);document.querySelector('#next').onclick=()=>billingPage(user,monthShift(month,1),filters);document.querySelector('#bulk').onclick=()=>bulkBilling(user,month,data,s);document.querySelector('#bsearch').onchange=()=>billingPage(user,month,{...filters,q:document.querySelector('#bsearch').value});document.querySelector('#bstatus').value=filters.status||'';document.querySelector('#bstatus').onchange=()=>billingPage(user,month,{...filters,status:document.querySelector('#bstatus').value});document.querySelector('#bproperty').onchange=()=>billingPage(user,month,{...filters,property_id:document.querySelector('#bproperty').value});document.querySelector('#butility').onchange=()=>billingPage(user,month,{...filters,utility:document.querySelector('#butility').value});
      document.querySelectorAll('[data-billing-preview]').forEach(n=>n.onclick=()=>previewBill(user,n.dataset.billingPreview,month));document.querySelectorAll('[data-billing-reading]').forEach(n=>n.onclick=()=>readingModal(user,n.dataset.billingReading,n.dataset.unit,n.dataset.utility,month));document.querySelectorAll('[data-billing-payment]').forEach(n=>n.onclick=()=>paymentModal(user,n.dataset.billingPayment));document.querySelectorAll('[data-billing-view]').forEach(n=>n.onclick=()=>location='/invoices/'+n.dataset.billingView);
    };
    shell(user,'Billing Center','<div class="loading">Loading monthly billing…</div>');load();
  }
  function billingRow(r){return `<tr><td>${esc(r.property)}</td><td><b>${esc(r.unit)}</b></td><td>${esc(r.tenant)}</td><td>${money(r.rent)}</td><td>${r.electricity?money(r.electricity):'—'}</td><td>${r.water?money(r.water):'—'}</td><td>${r.total?money(r.total):'—'}</td><td>${money(r.paid)}</td><td>${money(r.outstanding)}</td><td>${date(r.due_date)}${r.status==='OVERDUE'?`<br><small>${overdueDays(r.due_date)} day${overdueDays(r.due_date)===1?'':'s'} overdue</small>`:''}</td><td>${billingStatus(r.status)}</td><td><div class="actions">${r.status==='METER_READING_REQUIRED'?`<button class="btn secondary small" data-billing-reading="${esc(r.utilities.electricity.requires_reading?r.utilities.electricity.meter_id:r.utilities.water.meter_id)}" data-unit="${r.unit_id}" data-utility="${r.utilities.electricity.requires_reading?'electricity':'water'}">Add Reading</button>`:''}${r.invoice_id?`<button class="btn secondary small" data-billing-view="${r.invoice_id}">View</button>${r.outstanding!=='0.00'?`<button class="btn primary small" data-billing-payment="${r.invoice_id}">Payment</button>`:''}`:r.status==='READY'?`<button class="btn secondary small" data-billing-preview="${r.lease_id}">Preview</button>`:''}</div></td></tr>`;}
  function billingCard(r){return `<article class="billing-card"><div class="billing-card-head"><div><div class="muted">${esc(r.property)}</div><h3>${esc(r.unit)}</h3><div>${esc(r.tenant)}</div></div><div>${billingStatus(r.status)}</div></div><div class="billing-card-total">${r.total?money(r.total):'Not generated'}</div><div class="billing-card-grid"><span>Rent <b>${money(r.rent)}</b></span><span>Electricity <b>${r.electricity?money(r.electricity):'—'}</b></span><span>Water <b>${r.water?money(r.water):'—'}</b></span><span>Paid <b>${money(r.paid)}</b></span><span>Outstanding <b>${money(r.outstanding)}</b></span><span>Due <b>${date(r.due_date)}</b>${r.status==='OVERDUE'?`<small>${overdueDays(r.due_date)} days overdue</small>`:''}</span></div>${r.status==='METER_READING_REQUIRED'?`<div class="warning-box">⚠ Meter reading required <button class="btn secondary small" data-billing-reading="${esc(r.utilities.electricity.requires_reading?r.utilities.electricity.meter_id:r.utilities.water.meter_id)}" data-unit="${r.unit_id}" data-utility="${r.utilities.electricity.requires_reading?'electricity':'water'}">Add Reading</button></div>`:''}<div class="actions">${r.invoice_id?`<button class="btn secondary" data-billing-view="${r.invoice_id}">View</button>${r.outstanding!=='0.00'?`<button class="btn primary" data-billing-payment="${r.invoice_id}">Payment</button>`:''}`:r.status==='READY'?`<button class="btn primary" data-billing-preview="${r.lease_id}">Preview</button>`:''}</div></article>`;}
  async function previewBill(user,leaseId,month){try{const p=monthParts(month),x=await api('/billing/preview',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({lease_id:leaseId,billing_period_start:p.start,billing_period_end:p.end})});modal('Billing Preview',`<div class="preview-items">${x.items.map(i=>{const m=i.metadata||{};return `<div class="metric-line"><span>${esc(i.description)}<br><small>${esc(i.quantity)} × ${money(i.unit_rate)}</small>${m.previous_reading!=null?`<br><small>Previous ${esc(m.previous_reading)} → Current ${esc(m.current_reading)} = ${esc(m.consumption)} units @ ${money(m.rate_per_unit||i.unit_rate)}/unit</small>`:''}</span><b>${money(i.amount)}</b></div>`}).join('')}</div><div class="metric-line total-line"><b>Total</b><b>${money(x.total)}</b></div><div class="actions modal-actions"><button class="btn secondary" data-close-modal>Cancel</button><button class="btn primary" id="generate-now">Generate Invoice</button></div>`);document.querySelector('#generate-now').onclick=async()=>{const b=document.querySelector('#generate-now');b.disabled=true;try{const inv=await api('/billing/generate-invoice',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({lease_id:leaseId,billing_period_start:p.start,billing_period_end:p.end})});closeModal();toast('Invoice '+inv.invoice_number+' generated.');billingPage(user,month);}catch(e){b.disabled=false;showModalError(e.message);}};}catch(e){toast(e.message);}}
  async function bulkBilling(user,month,data,s){const ready=data.filter(r=>r.status==='READY');if(!ready.length){toast('No ready bills to generate.');return;}modal('Generate Bills',`<p>Generate invoices for <b>${ready.length}</b> ready unit${ready.length===1?'':'s'}?</p><div class="metric-line"><span>Expected total</span><b>${money(ready.reduce((a,r)=>a+Number(r.rent||0),0))} + utilities</b></div><div class="actions modal-actions"><button class="btn secondary" data-close-modal>Cancel</button><button class="btn primary" id="confirm-bulk">Generate Bills</button></div>`);document.querySelector('#confirm-bulk').onclick=async()=>{const b=document.querySelector('#confirm-bulk');b.disabled=true;try{const x=await api('/billing/generate-batch',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({month})});closeModal();modal('Billing completed',`<div class="status-grid"><div class="status-box">Generated<b>${x.generated}</b></div><div class="status-box">Skipped<b>${x.skipped}</b></div><div class="status-box">Needs meter reading<b>${x.needs_meter_reading}</b></div><div class="status-box">Already generated<b>${x.already_generated}</b></div><div class="status-box">Failed<b>${x.failed}</b></div></div><div class="actions modal-actions"><button class="btn primary" id="bulk-done">Done</button></div>`);document.querySelector('#bulk-done').onclick=()=>{closeModal();billingPage(user,month);};}catch(e){b.disabled=false;showModalError(e.message);}};}
  function modal(title,body){closeModal();const n=document.createElement('div');n.className='modal-backdrop';n.id='modal';n.innerHTML=`<div class="modal"><div class="section-head"><h2>${esc(title)}</h2><button class="icon-btn" data-close-modal>×</button></div><div id="modal-error" class="form-error"></div>${body}</div>`;document.body.appendChild(n);n.querySelectorAll('[data-close-modal]').forEach(b=>b.onclick=closeModal);}
  function closeModal(){document.querySelector('#modal')?.remove();}
  function showModalError(m){const n=document.querySelector('#modal-error');if(n)n.textContent=m;}
  async function readingModal(user,meterId,unitId,utility,month){if(!meterId){toast('No active '+utility+' meter is configured.');return;}modal('Add '+utility+' reading',`<div class="reading-context"><b>${esc(utility)}</b><span>Billing month: ${monthLabel(month)}</span></div><form id="modal-reading"><div class="form-grid">${input('New reading *','reading_value','','number','min="0" step="0.001"')}${input('Reading date *','reading_date',monthParts(month).end,'date')}</div>${select('Source','reading_source',[['manual','Manual'],['photo','Photo reference'],['imported','Imported']],'manual')}${input('Photo reference','photo_document_reference')}${input('Notes','notes')}<div class="form-actions"><button type="button" class="btn secondary" data-close-modal>Cancel</button><button class="btn primary">Save Reading</button></div></form>`);document.querySelector('#modal-reading').onsubmit=async e=>{e.preventDefault();const b=e.submitter;b.disabled=true;try{await api('/meters/'+meterId+'/readings',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(formData(e))});closeModal();toast('Meter reading saved.');billingPage(user,month);}catch(x){b.disabled=false;showModalError(x.message);}};}
  async function paymentModal(user,invoiceId){try{const inv=await api('/invoices/'+invoiceId);modal('Record Payment',`<div class="metric-line"><span>${esc(inv.invoice_number)}<br>${esc(inv.tenant_name)} · ${esc(inv.property_name)} · ${esc(inv.unit_number)}</span><b>${money(inv.amount_due)} due</b></div><form id="modal-payment"><div class="form-grid">${input('Amount *','amount','','number','min="0.01" step="0.01" max="'+esc(inv.amount_due)+'"')}${input('Payment date *','payment_date',today(),'date')}</div>${select('Payment method','payment_method',[['cash','Cash'],['upi','UPI'],['bank_transfer','Bank Transfer'],['card','Card'],['other','Other']],'upi')}${input('Transaction reference','transaction_reference')}${input('Notes','notes')}<div class="form-actions"><button type="button" class="btn secondary" data-close-modal>Cancel</button><button class="btn primary">Record Payment</button></div></form>`);document.querySelector('#modal-payment').onsubmit=async e=>{e.preventDefault();const b=e.submitter;b.disabled=true;try{await api('/payments',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({invoice_id:invoiceId,...formData(e)})});closeModal();toast('Payment recorded successfully.');billingPage(user,new Date(inv.billing_period_start).toISOString().slice(0,7));}catch(x){b.disabled=false;showModalError(x.message);}};}catch(e){toast(e.message);}}
  async function invoiceDetail(user,id){shell(user,'Invoice','<div id="invoice-detail" class="loading">Loading invoice…</div>');try{const x=await api('/invoices/'+id);const items=Array.isArray(x.items)?x.items:[],payments=Array.isArray(x.payments)?x.payments:[];document.querySelector('#invoice-detail').innerHTML=head('Billing','Invoice '+x.invoice_number,x.property_name+' · '+x.unit_number+' · '+x.tenant_name,'<button class="btn secondary" onclick="history.back()">Back</button><a class="btn secondary" href="/documents?entity_type=INVOICE&entity_id='+id+'">Documents</a>'+(Number(x.amount_due)>0?'<button class="btn primary" id="pay">Record Payment</button>':'') )+`<div class="grid-2"><section class="card"><h2>Invoice details</h2><div class="metric-line"><span>Tenant</span><b>${esc(x.tenant_name)}</b></div><div class="metric-line"><span>Property / Unit</span><b>${esc(x.property_name)} · ${esc(x.unit_number)}</b></div><div class="metric-line"><span>Billing period</span><b>${date(x.billing_period_start)} — ${date(x.billing_period_end)}</b></div><div class="metric-line"><span>Due date</span><b>${date(x.due_date)}</b></div><div class="metric-line"><span>Status</span>${status(x.status)}</div></section><section class="card"><h2>Balance</h2><div class="metric-line"><span>Total</span><b>${money(x.total)}</b></div><div class="metric-line"><span>Paid</span><b>${money(x.amount_paid)}</b></div><div class="metric-line"><span>Outstanding</span><b>${money(x.amount_due)}</b></div></section></div><section class="card section"><h2>Line items</h2>${items.map(i=>{const m=i.metadata||{};return `<div class="invoice-item"><div class="metric-line"><span><b>${esc(i.description)}</b><br><small>${esc(i.quantity)} × ${money(i.unit_rate)}</small>${m.previous_reading!=null?`<br><small>Previous: ${esc(m.previous_reading)} · Current: ${esc(m.current_reading)} · Consumption: ${esc(m.consumption)} · Rate: ${money(m.rate_per_unit||i.unit_rate)}/unit</small>`:''}</span><b>${money(i.amount)}</b></div></div>`}).join('')}</section><section class="card section"><h2>Payment history</h2>${payments.length?`<div class="table-wrap"><table class="table"><thead><tr><th>Date</th><th>Amount</th><th>Method</th><th>Reference</th></tr></thead><tbody>${payments.map(p=>`<tr><td>${date(p.payment_date)}</td><td><b>${money(p.amount)}</b></td><td>${esc(p.payment_method)}</td><td>${esc(p.transaction_reference||'—')}</td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">No payments recorded.</div>'}</section>`;if(document.querySelector('#pay'))document.querySelector('#pay').onclick=()=>paymentModal(user,id);}catch(e){document.querySelector('#invoice-detail').innerHTML='<div class="error">'+esc(e.message)+'</div>';}}
  async function notificationsPage(user,filter='all'){let data;try{data=await api('/notifications?filter='+encodeURIComponent(filter)+'&limit=50');}catch(e){shell(user,'Notifications',head('Alerts','Notifications','Unable to load notifications.')+'<div class="error">'+esc(e.message)+'</div>');return;}const tabs=[['all','All'],['unread','Unread'],['payments','Payments'],['invoices','Invoices'],['rent','Rent'],['meter','Meter'],['lease','Lease']];const icon=t=>({PAYMENT_RECEIVED:'💰',INVOICE_GENERATED:'📄',RENT_DUE_SOON:'🔔',RENT_DUE_TODAY:'🔔',RENT_OVERDUE:'⚠',METER_READING_REQUIRED:'⚡',LEASE_EXPIRING:'📅',SYSTEM:'ℹ'}[t]||'🔔');const body=head('Alerts','Notifications','Rent, billing, meter and lease reminders.','<button class="btn secondary" id="read-all">Mark all as read</button>')+'<div class="notification-tabs">'+tabs.map(t=>'<button class="'+(filter===t[0]?'active':'')+'" data-filter="'+t[0]+'">'+t[1]+'</button>').join('')+'</div><section class="card"><div class="notification-list">'+(data.items.length?data.items.map(n=>`<article class="notification-item ${n.status==='PENDING'?'unread':''}" data-notification-id="${n.id}"><div class="notification-icon">${icon(n.type)}</div><div class="notification-copy"><div class="notification-title"><b>${esc(n.title)}</b><small>${new Date(n.created_at).toLocaleString('en-IN',{day:'2-digit',month:'short',hour:'2-digit',minute:'2-digit'})}</small></div><p>${esc(n.message)}</p><div class="notification-actions">${n.invoice_id?`<a href="/invoices/${n.invoice_id}">View invoice</a>`:''}${n.lease_id?`<a href="/leases/${n.lease_id}">View lease</a>`:''}<button class="btn secondary small" data-read="${n.id}" ${n.status==='READ'?'disabled':''}>${n.status==='READ'?'Read':'Mark read'}</button></div></div></article>`).join(''):'<div class="empty">No notifications in this view.</div>')+'</div></section>';shell(user,'Notifications',body);document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>notificationsPage(user,b.dataset.filter));document.querySelectorAll('[data-read]').forEach(b=>b.onclick=async()=>{b.disabled=true;try{await api('/notifications/'+b.dataset.read+'/read',{method:'POST'});notificationsPage(user,filter);}catch(e){b.disabled=false;toast(e.message);}});document.querySelector('#read-all').onclick=async()=>{try{await api('/notifications/read-all',{method:'POST'});notificationsPage(user,filter);}catch(e){toast(e.message);}};}
  async function settingsPage(user){try{const [x,ai]=await Promise.all([api('/notifications/preferences'),api('/ai/automation/preferences')]);const labels={INVOICE_GENERATED:'Invoice generated',PAYMENT_RECEIVED:'Payment received',RENT_DUE_SOON:'Rent due soon',RENT_DUE_TODAY:'Rent due today',RENT_OVERDUE:'Overdue',METER_READING_REQUIRED:'Meter reading required',LEASE_EXPIRING:'Lease expiring'};const prefs=x.preferences||[],rules=x.rules||[];shell(user,'Settings',head('Preferences','Settings','Configure in-app reminders and notification behavior.')+'<form id="notification-settings"><section class="card"><h2>Notifications</h2><div class="settings-list">'+prefs.map(p=>`<label class="setting-row"><span><b>${labels[p.notification_type]||p.notification_type}</b><small>In-app notification</small></span><input type="checkbox" name="pref" data-type="${p.notification_type}" ${p.enabled?'checked':''}></label>`).join('')+'</div></section><section class="card section"><h2>Reminder timing</h2><div class="settings-list">'+rules.map(r=>`<label class="setting-row"><span><b>${labels[r.notification_type]||r.rule_key}</b><small>${r.rule_key==='RENT_OVERDUE_WEEKLY'?'Additional overdue reminder':r.rule_key==='METER_READING_REQUIRED'?'Days before billing':r.rule_key==='LEASE_EXPIRING'?'Days before lease end':'Days from due date'}</small></span><span class="setting-control"><input type="number" min="0" name="days" data-rule="${r.rule_key}" value="${r.days_offset}"> days <input type="checkbox" name="rule" data-rule-enabled="${r.rule_key}" ${r.enabled?'checked':''}></span></label>`).join('')+'</div></section><section class="card section"><label class="setting-row"><span><b>Notification retention</b><small>Old notification records only</small></span><input id="retention" type="number" min="30" max="3650" value="${prefs[0]?.retention_days||180}"> days</label></section><div class="form-actions"><button class="btn primary">Save notification settings</button></div></form><section class="card section"><div class="section-head"><h2>AI Automation</h2><span class="muted">Owner-controlled, in-app only</span></div><p class="muted">Configure insight alerts and scheduled briefings. AI drafts require review and reconciliation suggestions require explicit acceptance.</p><div class="actions"><a class="btn secondary" href="/ai-automation">Automation preferences</a><a class="btn secondary" href="/ai-briefings">Briefings</a><a class="btn secondary" href="/ai-drafts">Communication drafts</a><a class="btn secondary" href="/ai-reconciliation">Reconciliation suggestions</a></div></section><section class="card section"><div class="section-head"><h2>Financial Operations</h2><span class="muted">Controls and traceability</span></div><div class="actions"><a class="btn secondary" href="/recurring-expenses">Recurring Expenses</a><a class="btn secondary" href="/financial-periods">Financial Periods</a><a class="btn secondary" href="/reconciliation">Reconciliation</a><a class="btn secondary" href="/audit">Audit</a></div></section>');document.querySelector('#notification-settings').onsubmit=async e=>{e.preventDefault();const preferences=prefs.map(p=>({notification_type:p.notification_type,enabled:document.querySelector(`[data-type="${p.notification_type}"]`).checked,channel:'IN_APP',retention_days:Number(document.querySelector('#retention').value||180)}));const outRules=rules.map(r=>({rule_key:r.rule_key,enabled:document.querySelector(`[data-rule-enabled="${r.rule_key}"]`).checked,days_offset:Number(document.querySelector(`[data-rule="${r.rule_key}"]`).value||0)}));try{await api('/notifications/preferences',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({preferences,rules:outRules})});toast('Notification settings saved.');}catch(e){toast(e.message);}};}catch(e){shell(user,'Settings',head('Preferences','Settings','Unable to load settings.')+'<div class="error">'+esc(e.message)+'</div>');}}
  async function paymentsPage(user){let q=new URLSearchParams(location.search),data;try{data=await api('/payments/operations?limit=50&page='+(q.get('page')||1)+(q.get('source')?'&source='+encodeURIComponent(q.get('source')):''));}catch(e){shell(user,'Payments',head('Payments','Payment operations','Unable to load payments.')+'<div class="error">'+esc(e.message)+'</div>');return}const s=await api('/payments/config').catch(()=>({status:'Not configured',message:'Online payments are not configured.'}));shell(user,'Payments',head('Payments','Manual and online gateway payment operations.','<a class="btn secondary" href="/settings/payments">Gateway settings</a>')+`<section class="card"><div class="safe-note">Gateway: <b>${esc(s.provider)}</b> · ${esc(s.status)} · ${esc(s.mode)}</div><div class="table-wrap"><table class="table"><thead><tr><th>Date</th><th>Tenant</th><th>Invoice</th><th>Amount</th><th>Source</th><th>Provider</th><th>Status</th><th>Reference</th></tr></thead><tbody>${data.items?.length?data.items.map(p=>`<tr class="link" onclick="location='/payments/${p.id}'"><td>${date(p.payment_date)}</td><td>${esc(p.tenant_name)}</td><td>${esc(p.invoice_number)}</td><td><b>${money(p.amount)}</b></td><td>${esc(p.source||'MANUAL')}</td><td>${esc(p.provider||'—')}</td><td>${esc(p.transaction_status||'RECORDED')}</td><td>${esc(p.transaction_reference||'—')}</td></tr>`).join(''):'<tr><td colspan="8" class="empty">No payments found.</td></tr>'}</tbody></table></div></section>`)}async function paymentDetail(user,id){try{const x=await api('/payments/'+id);shell(user,'Payment',head('Payment detail',x.invoice_number||'Payment lifecycle','<a class="btn secondary" href="/payments">Back</a>')+`<div class="grid-2"><section class="card"><h2>Payment</h2><div class="metric-line"><span>Tenant</span><b>${esc(x.tenant_name)}</b></div><div class="metric-line"><span>Invoice</span><b>${esc(x.invoice_number)}</b></div><div class="metric-line"><span>Amount</span><b>${money(x.amount)}</b></div><div class="metric-line"><span>Source</span><b>${esc(x.source||'MANUAL')}</b></div><div class="metric-line"><span>Method</span><b>${esc(x.payment_method)}</b></div><div class="metric-line"><span>Reference</span><b>${esc(x.transaction_reference||'—')}</b></div></section><section class="card"><h2>Gateway</h2><div class="metric-line"><span>Provider</span><b>${esc(x.provider||'—')}</b></div><div class="metric-line"><span>Status</span><b>${esc(x.transaction_status||'RECORDED')}</b></div><div class="metric-line"><span>Provider payment ID</span><b>${esc(x.provider_payment_id||'—')}</b></div><div class="metric-line"><span>Paid at</span><b>${x.paid_at?new Date(x.paid_at).toLocaleString('en-IN'):'—'}</b></div>${x.transaction_id&&x.transaction_status==='CAPTURED'?`<button class="btn secondary" id="refund">Request refund</button>`:''}</section></div><section class="card section"><h2>Refunds</h2>${x.refunds?.length?x.refunds.map(r=>`<div class="metric-line"><span>${esc(r.reason)}<br><small>${date(r.created_at)}</small></span><b>${money(r.amount)} · ${esc(r.status)}</b></div>`).join(''):'<div class="empty">No refunds.</div>'}</section><section class="card section"><h2>Receipt</h2>${x.receipt?`<div class="metric-line"><span>Receipt number</span><b>${esc(x.receipt.receipt_number)}</b></div><div class="metric-line"><span>Receipt date</span><b>${date(x.receipt.receipt_date)}</b></div>`:'<div class="safe-note">Receipt metadata will be created after a verified online payment. No fake PDF is generated.</div>'}</section>`);if(document.querySelector('#refund'))document.querySelector('#refund').onclick=async()=>{const amount=prompt('Refund amount (leave blank for full refundable balance):');const reason=prompt('Refund reason:');if(!reason)return;try{await api('/payments/'+id+'/refund',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({confirm:true,amount:amount||undefined,reason})});toast('Refund submitted.');paymentDetail(user,id)}catch(e){toast(e.message)}}}catch(e){shell(user,'Payment',head('Payment','Unable to load payment.')+'<div class="error">'+esc(e.message)+'</div>')}}async function paymentSettingsPage(user){try{const s=await api('/payments/config');shell(user,'Payment Settings',head('Payment Gateway','Server-side gateway configuration status.','<a class="btn secondary" href="/payments">Payment center</a>')+`<section class="card"><h2>Payment Gateway</h2><div class="metric-line"><span>Provider</span><b>${esc(s.provider)}</b></div><div class="metric-line"><span>Status</span><b>${esc(s.status)}</b></div><div class="metric-line"><span>Mode</span><b>${esc(s.mode)}</b></div><div class="metric-line"><span>Webhook</span><b>${esc(s.webhook)}</b></div><p class="safe-note">Secrets are managed by Hatchable secret configuration and are never stored in PostgreSQL, rendered in this UI, exposed to tenants, logs, audit records, or AI.</p><p class="safe-note">${esc(s.message)}</p></section><section class="card section"><h2>Configuration</h2><p>To enable live payments, select a provider in the project configuration and provide the corresponding public key, server secret, and webhook signing secret through Hatchable's secret setup. This screen never accepts or stores gateway secrets.</p></section>`)}catch(e){shell(user,'Payment Settings',head('Payment Gateway','Unable to load gateway status.')+'<div class="error">'+esc(e.message)+'</div>')}}function placeholder(user,title){shell(user,title,head('Workspace',title,'This feature is intentionally outside Step 8 scope.','<span class="pill">Coming soon</span>')+'<div class="card empty"><strong>Not implemented yet.</strong>AI, WhatsApp, gateway, maintenance and tenant portal remain intentionally deferred.</div>');}
  async function boot(){if(window.__RENTAL_APP_BOOTED)return;showRouteLoader();window.__RENTAL_APP_BOOTED=true;let u;try{u=await getUser();}catch(e){const b=document.querySelector('#boot');if(b)b.innerHTML='<div><strong>Unable to verify your account.</strong><br><span style="opacity:.7">'+esc(e.message||'Please try again.')+'</span></div>';return;}if(!u)return;const p=location.pathname.replace(/\/$/,'')||'/';if(p==='/'||p==='/dashboard')return dashboard(u);if(p==='/properties')return properties(u);if(/^\/properties\/[^/]+\/units$/.test(p))return propertyUnits(u,p.split('/')[2]);if(/^\/properties\/[^/]+\/units\/[^/]+$/.test(p))return unitDetail(u,p.split('/')[2],p.split('/')[4]);if(p.startsWith('/properties/'))return propertyDetail(u,p.split('/')[2]);if(p==='/tenants')return tenants(u);if(p.startsWith('/tenants/'))return tenantDetail(u,p.split('/')[2]);if(p==='/leases')return leases(u);if(p.startsWith('/leases/'))return leaseDetail(u,p.split('/')[2]);if(p==='/documents')return location.replace('/documents/index.html'+location.search);if(p==='/documents/requirements')return location.replace('/documents/index.html?requirements=1');if(p==='/assistant')return location.replace('/assistant/index.html'+location.search);if(p==='/billing')return billingPage(u,new URLSearchParams(location.search).get('month')||new Date().toISOString().slice(0,7),{status:new URLSearchParams(location.search).get('status')||''});if(p==='/notifications')return notificationsPage(u);if(p==='/invoices')return placeholder(u,'Invoices');if(p.startsWith('/invoices/'))return invoiceDetail(u,p.split('/')[2]);if(p==='/payments')return paymentsPage(u);if(/^\/payments\/[^/]+$/.test(p))return paymentDetail(u,p.split('/')[2]);if(p==='/settings/payments')return paymentSettingsPage(u);if(['/utilities','/maintenance','/reports'].includes(p))return placeholder(u,p.slice(1).replace(/^./,x=>x.toUpperCase()));if(p==='/settings')return settingsPage(u);return dashboard(u);}
  // app.js is the single bootstrap owner. app-main.js only defines the
